function frame(id,H=320){const svg=$(id),W=Math.max(320,svg.getBoundingClientRect().width),small=W<600,L=small?46:62,R=small?58:72,T=26,B=H-33;svg.setAttribute('viewBox','0 0 '+W+' '+H);svg.replaceChildren();return{svg,W,L,R,T,B,H,small};}
