function metric(){const f=frame('metricSvg'),kind=$('metricChoice').value,nav=$('showNav').checked,byDate=new Map(S.rows.map(r=>[r.date,r])),rows=S.prices.map(p=>({...p,r:byDate.get(p.date)})),dates=rows.map(r=>r.date),get=(r,n=false)=>kind==='ratio'?r?.[n?'navRatioPct':'marketRatioPct']:kind==='prior'?rankPct(r?.[n?'navPriorRank':'marketPriorRank']):rankPct(r?.[n?'navRank':'marketRank']),values=rows.map(p=>{const v=get(p.r);return p.r&&Number.isFinite(v)?v:null;}),navValues=rows.map(p=>{const v=get(p.r,true);return p.r&&Number.isFinite(v)?v:null;}),hi=kind==='ratio'?Math.max(.1,...values.filter(Number.isFinite),...(nav?navValues.filter(Number.isFinite):[]))*1.1:100,plo=Math.min(...rows.map(p=>p.close))*.97,phi=Math.max(...rows.map(p=>p.close))*1.03,x=i=>f.L+i/(rows.length-1)*(f.W-f.L-f.R),y=v=>f.B-v/hi*(f.B-f.T),py=v=>f.B-(v-plo)/(phi-plo)*(f.B-f.T);axes(f,{lo:0,hi,label:kind==='ratio'?'占比（%）':'分位（%）',dp:kind==='ratio'?1:0},{lo:plo,hi:phi},dates);f.svg.append(node('path',{d:path(rows.map(p=>p.close),x,py),fill:'none',stroke:'#c56e38','stroke-width':1.5,'vector-effect':'non-scaling-stroke'}),node('path',{d:path(values,x,y),fill:'none',stroke:'#147d7a','stroke-width':1.8,'vector-effect':'non-scaling-stroke'}));if(nav)f.svg.append(node('path',{d:path(navValues,x,y),fill:'none',stroke:'#4c568f','stroke-dasharray':'5 3','stroke-width':1.7,'vector-effect':'non-scaling-stroke'}));const hover=node('g',{visibility:'hidden'});f.svg.append(hover);states.metric={...f,rows,x,y,hover,current:rows.length-1};show('metric',rows.length-1,false);}
